INSERT OR IGNORE INTO monsters (name, description, monster_type, level, dexterity_die, insight_die, might_die, willpower_die, hp, mp, initiative, defense, magic_defense, equipment, img_key, is_villain, ultima_points, strategy, source_page) VALUES ('Dracoardil', 'Essas plantas colossais merecem seu nome: suas bocarras são grandes o suficiente para engolir os membros de um dragão adulto. No entanto, elas são mais usadas para capturar e digerir animais e humanoides.
A única boa notícia sobre essas monstruosidades é que estão enraizadas nas profundezas do solo — você ainda pode fugir delas, contanto que consiga escapar de suas vinhas letais.', 'plant', 20, 'd8', 'd8', 'd10', 'd8', 90, 60, 8, 0, 0, NULL, 'dracoardil', 0, 0, NULL, 353);
